/** Group an array by a key function. */
export function groupBy(arr: any[], keyFn: (item: any) => any): Record<any, any[]> {
  return arr.reduce((acc, item) => {
    const key = keyFn(item);
    if (!acc[key]) acc[key] = [];
    acc[key].push(item);
    return acc;
  }, {});
}

/** Pick specific keys from an object. */
export function pick(obj: any, keys: string[]): any {
  return keys.reduce((acc: any, key) => {
    if (key in obj) acc[key] = obj[key];
    return acc;
  }, {});
}

/** Omit specific keys from an object. */
export function omit(obj: any, keys: string[]): any {
  return Object.fromEntries(
    Object.entries(obj).filter(([k]) => !keys.includes(k))
  );
}

/** Deep merge two objects (second overrides first). */
export function merge(target: any, source: any): any {
  const result = { ...target };
  for (const key of Object.keys(source)) {
    if (typeof source[key] === 'object' && source[key] !== null && !Array.isArray(source[key])) {
      result[key] = merge(target[key] || {}, source[key]);
    } else {
      result[key] = source[key];
    }
  }
  return result;
}

// TODO: add generic utility type
// DeepPartial<T> should make all properties and nested properties optional
export type DeepPartial<T> = T;

