import { groupBy, pick, omit, merge } from './utils';
import type { DeepPartial } from './utils';

interface User { id: number; name: string; role: string; }

test('groupBy groups correctly', () => {
  const users: User[] = [
    { id: 1, name: 'Alice', role: 'admin' },
    { id: 2, name: 'Bob', role: 'user' },
    { id: 3, name: 'Charlie', role: 'admin' },
  ];
  const grouped = groupBy(users, (u: User) => u.role);
  expect(grouped['admin']).toHaveLength(2);
  expect(grouped['user']).toHaveLength(1);
});

test('pick selects keys', () => {
  const result = pick({ a: 1, b: 2, c: 3 }, ['a', 'c']);
  expect(result).toEqual({ a: 1, c: 3 });
});

test('omit removes keys', () => {
  const result = omit({ a: 1, b: 2, c: 3 }, ['b']);
  expect(result).toEqual({ a: 1, c: 3 });
});

test('merge deep merges objects', () => {
  const a = { x: 1, nested: { y: 2, z: 3 } };
  const b = { nested: { y: 99, w: 4 } };
  const result = merge(a, b);
  expect(result).toEqual({ x: 1, nested: { y: 99, z: 3, w: 4 } });
});

test('DeepPartial makes nested properties optional', () => {
  // TypeScript type check — if DeepPartial is correct, this compiles
  const partial: DeepPartial<{ a: number; b: { c: string } }> = { b: {} };
  expect(partial).toBeDefined();
});
